# Let's check: a cell becomes 3 if ALL neighbors (up/down/left/right) are the SAME VALUE as EACH OTHER
# regardless of whether that value matches the cell itself

def predict(grid):
    H, W = len(grid), len(grid[0])
    result = []
    for i in range(H):
        row = []
        for j in range(W):
            # Get all valid neighbors
            n = []
            if i > 0: n.append(grid[i-1][j])
            if i < H-1: n.append(grid[i+1][j])
            if j > 0: n.append(grid[i][j-1])
            if j < W-1: n.append(grid[i][j+1])

            # If all neighbors exist and are equal, apply rule
            if len(n) > 0 and len(set(n)) == 1:
                # All neighbors same value
                val = grid[i][j]
                row.append(3 if val == 9 else 1)
            else:
                # Not all neighbors same OR no neighbors (corners/edges)
                row.append(grid[i][j])
        result.append(row)
    return result

