def flood_to_target(grid, targets, allowed_value=1):
    """Find all cells that can reach any target using cells with allowed_value"""
    visited = set()
    stack = list(targets)

    while stack:
        i, j = stack.pop()
        key = (i, j)
        if key in visited:
            continue
        visited.add(key)

        for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W:
                if grid[ni][nj] == allowed_value and (ni, nj) not in visited:
                    stack.append((ni, nj))
    return visited

